{"path": "stage1.py", "content": """"Stage 1: read the orders CSV into a list of dicts."""

import csv


def parse_orders(path):
    """Read ``path`` (header ``id,qty,price``) and return rows as
    ``[{"id": int, "qty": int, "price": int}, ...]`` in file order."""
    rows = []
    with open(path, newline="") as fh:
        reader = csv.DictReader(fh)
        for row in reader:
            rows.append(
                {
                    "id": int(row["id"]),
                    "qty": int(row["qty"]),
                    "price": int(row["price"]),
                }
            )
    return rows
"}

{"path": "stage2.py", "content": """"Stage 2: drop rows whose quantity is not positive."""


def filter_orders(rows):
    """Return the rows with ``qty > 0``, preserving the original order."""
    return [row for row in rows if row["qty"] > 0]
"}

{"path": "stage3.py", "content": """"Stage 3: aggregate quantities by price."""


def total_by_price(rows):
    """Return ``{price: total_qty}``, summing qty across equal prices."""
    totals = {}
    for row in rows:
        price = row["price"]
        totals[price] = totals.get(price, 0) + row["qty"]
    return totals
"}

{"path": "stage4.py", "content": """"Stage 4: render the totals mapping as a text report."""


def report(totals):
    """Return ``"<price>:<qty>"`` lines sorted by ascending price, newline-terminated."""
    lines = [f"{price}:{totals[price]}" for price in sorted(totals)]
    return "".join(line + "\n" for line in lines)
"}
